// Offline stand-in for the network: one python process runs the real contract, a tiny HTTP server plays the RPC.
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { createInterface } from "node:readline";

const MARK = "@@RPC ";
const root = process.env.REHEARSAL_ROOT;
const pending = new Map();
let nextId = 1;
let ready;
const readyPromise = new Promise((r) => (ready = r));

const child = spawn("bash", ["-c", `. /home/claude/env.sh; cd "${root}" && python3 -m pytest -q -s -p no:cacheprovider -c pytest.ini rehearsal/rehearsal_server.py`], {
  stdio: ["pipe", "pipe", "inherit"],
  env: process.env,
});
child.on("exit", () => process.exit(process.exitCode ?? 0));
createInterface({ input: child.stdout }).on("line", (line) => {
  if (!line.startsWith(MARK)) return;
  const msg = JSON.parse(line.slice(MARK.length));
  if (msg.ready) return ready();
  const p = pending.get(msg.id);
  if (p) {
    pending.delete(msg.id);
    p(msg);
  }
});
export function stop() {
  try {
    child.stdin.end();
  } catch {}
}
process.on("exit", () => {
  try {
    child.kill();
  } catch {}
});

const replacer = (_k, v) => (typeof v === "bigint" ? { $big: v.toString() } : v);
export async function ask(req) {
  await readyPromise;
  const id = nextId++;
  const p = new Promise((resolve) => pending.set(id, resolve));
  child.stdin.write(JSON.stringify({ ...req, id, now: Math.floor(Date.now() / 1000) }, replacer) + "\n");
  return p;
}

const server = createServer((req, res) => {
  let body = "";
  req.on("data", (d) => (body += d));
  req.on("end", async () => {
    const q = JSON.parse(body);
    const reply = (result, error) => {
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify(error ? { jsonrpc: "2.0", id: q.id, error: { message: error } } : { jsonrpc: "2.0", id: q.id, result }));
    };
    if (q.method === "eth_chainId") return reply("0x1");
    if (q.method === "eth_getBalance") {
      const r = await ask({ op: "balance", address: q.params[0] });
      return reply("0x" + BigInt(r.ret).toString(16));
    }
    if (q.method === "sim_fundAccount") {
      // the number may exceed 2^53, so it is read from the raw text
      const m = body.match(/"params":\["(0x[0-9a-fA-F]+)",(\d+)\]/);
      await ask({ op: "fund", address: m[1], amount: m[2] });
      return reply(null);
    }
    reply(null, `unsupported ${q.method}`);
  });
});
export const port = await new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server.address().port)));
